new = '''def check_request(req, got):
    services = req['services']
    rules = req['rules']
    dfa = got['dfa']
    nexts = dfa['next']
    acc = dfa['accept']
    n = len(services)
    tidx = {s: i for i, s in enumerate(services)}
    problems = []
    k = len(nexts)
    if len(nexts) != len(acc) or len(acc) != len(dfa['distance']):
        return ['length mismatch']
    for row in nexts:
        if len(row) != n:
            problems.append('row width')
        for t in row:
            if not (0 <= t < k):
                problems.append('bad target')
    if problems:
        return problems
    seen = set()
    stack = [0]
    while stack:
        s = stack.pop()
        if s in seen:
            continue
        seen.add(s)
        for t in nexts[s]:
            if t not in seen:
                stack.append(t)
    if len(seen) != k:
        problems.append('unreachable states')

    # language equivalence against the direct predicate, words up to bound
    bound = 5
    words = [[]]
    for _ in range(bound):
        words = words + [w + [s] for w in words for s in services]
    def run_word(w):
        st = 0
        for tok in w:
            st = nexts[st][tidx[tok]]
        return acc[st]
    for w in words:
        if run_word(w) != ref_impl.ref_language_ok(services, rules, w):
            problems.append('language mismatch on %r' % (w,))
            break

    # reach word for every state
    reach_word = {0: []}
    dq = [0]
    while dq:
        s = dq.pop(0)
        for a in range(n):
            t = nexts[s][a]
            if t not in reach_word:
                reach_word[t] = reach_word[s] + [services[a]]
                dq.append(t)

    # accept flag consistency at reaching words
    for s in range(k):
        if acc[s] != ref_impl.ref_language_ok(services, rules, reach_word[s]):
            problems.append('accept flag wrong at %d' % s)

    # internal minimality: no two states equivalent inside the DFA
    memo = {}

    def inequiv(a, b):
        if a == b:
            return False
        key = (a, b) if a < b else (b, a)
        if key in memo:
            return memo[key]
        memo[key] = True  # assume inequivalent while recursing (cycle safe)
        res = False
        if acc[a] != acc[b]:
            res = True
        else:
            for x in range(n):
                if inequiv(nexts[a][x], nexts[b][x]):
                    res = True
                    break
        memo[key] = res
        return res

    for a in range(k):
        for b in range(a + 1, k):
            if not inequiv(a, b):
                problems.append('states %d and %d equivalent' % (a, b))
                break

    # semantic minimality on tiny instances via predicate residuals
    if n <= 3 and k <= 10:
        lim = k + 2
        residuals = []
        for s in range(k):
            u = reach_word[s]
            accs = []
            stack = [[]]
            while stack:
                w = stack.pop()
                accs.append(1 if ref_impl.ref_language_ok(services, rules,
                                                           u + w) else 0)
                if len(w) < lim:
                    for tok in services:
                        stack.append(w + [tok])
            residuals.append(tuple(accs))
        if len(set(residuals)) != k:
            problems.append('not minimal (predicate residuals)')

    # distances: internal BFS consistency
    from collections import deque as _dq
    dist = dfa['distance']
    rev = [[] for _ in range(k)]
    for s in range(k):
        for a, t in enumerate(nexts[s]):
            rev[t].append(s)
    want = [None] * k
    q = _dq()
    for s in range(k):
        if acc[s]:
            want[s] = 0
            q.append(s)
    while q:
        u = q.popleft()
        for v in rev[u]:
            if want[v] is None:
                want[v] = want[u] + 1
                q.append(v)
    if want != dist:
        problems.append('distance mismatch')

    # queries consistent with the DFA
    for q0, res in zip(req['queries'], got['queries']):
        st = 0
        for tok in q0:
            st = nexts[st][tidx[tok]]
        if res['state'] != st or res['allow'] != acc[st] or \\
                res['distance'] != dist[st]:
            problems.append('query mismatch')
    return problems


'''
